<script>document.addEventListener('DOMContentLoaded',()=>{const b=document.querySelector('[data-x325-menu]'),n=document.querySelector('[data-x325-nav]');b?.addEventListener('click',()=>n?.classList.toggle('is-open'));document.querySelectorAll('[data-x325-slider]').forEach(s=>{const slides=[...s.querySelectorAll('[data-x325-slide]')];if(slides.length<2)return;let i=0;setInterval(()=>{slides[i].classList.remove('is-active');i=(i+1)%slides.length;slides[i].classList.add('is-active')},Number(s.dataset.autoplay||6000))});document.querySelectorAll('[data-x325-faq]').forEach(x=>x.querySelector('button')?.addEventListener('click',()=>x.classList.toggle('is-open')));});</script>
